/* <<< Übersetzungs-Ergänzungen <<< */













function t(key) {
    const lang = (appData && appData.settings && appData.settings.language) ? appData.settings.language : 'de';
    return i18n[lang][key] || i18n['de'][key] || key;
}

/* Global erreichbare Übersetzungs-Helfer. In app.js heißt in vielen Schleifen die Laufvariable „t"
   (eine Aufgabe) – dort wäre t('…') kein Funktionsaufruf mehr. _t / _tf sind davon unabhängig. */
function _t(key) { return t(key); }
function _tf(key, vars) { let s = t(key); for (const k in (vars || {})) s = s.split('{' + k + '}').join(vars[k]); return s; }

/* Unveränderte Standard-Spalten (Zu erledigen / In Bearbeitung / Prüfung) in die gewählte Sprache bringen.
   Vom Benutzer umbenannte Spalten bleiben unangetastet. */
function localizeDefaultStatuses() {
    if (!appData || !Array.isArray(appData.statuses)) return;
    const DEF = { todo: 'st_def_todo', inProgress: 'st_def_inprogress', review: 'st_def_review' };
    appData.statuses.forEach(s => {
        const k = DEF[s.id];
        if (k && ['de', 'en', 'fr'].some(l => i18n[l] && i18n[l][k] === s.title)) s.title = t(k);
    });
}

function applyTranslations() {
    localizeDefaultStatuses();
    document.querySelectorAll('[data-i18n]').forEach(el => {
        const key = el.getAttribute('data-i18n');
        const txt = t(key);
        if (el.tagName === 'INPUT' && (el.type === 'text' || el.type === 'number')) {
            el.placeholder = txt;
        } else if (el.tagName === 'OPTION') {
            el.innerText = txt;
        } else {
            /* Führendes Icon behalten: Viele Überschriften/Buttons haben vor dem Text ein <i>-Icon,
               das beim Ersetzen von innerHTML sonst verloren ginge. */
            const icon = el.firstElementChild && el.firstElementChild.tagName === 'I' ? el.firstElementChild : null;
            if (icon && txt.indexOf('<i ') === -1) el.innerHTML = icon.outerHTML + ' ' + txt;
            else el.innerHTML = txt;
        }
    });
    document.querySelectorAll('[data-i18n-title]').forEach(el => {
        el.title = t(el.getAttribute('data-i18n-title'));
    });
    document.querySelectorAll('[data-i18n-placeholder]').forEach(el => {
        el.placeholder = t(el.getAttribute('data-i18n-placeholder'));
    });
    document.querySelectorAll('[data-i18n-aria]').forEach(el => {
        el.setAttribute('aria-label', t(el.getAttribute('data-i18n-aria')));
    });
    document.documentElement.lang = (appData && appData.settings && appData.settings.language) || 'de';
    document.title = t('app_title');
    // This function exists in app.js, so it will be called correctly from the global scope
    if (typeof updateShortcutUI === 'function') {
        updateShortcutUI();
    }
}